; ==============================================================================================
; BIOS ПЕОМ «Практик», версія 2.14-15 (2.14-15_dk/2.14-15_dk.rom, 16 КБ, CRC32 8F2C3569)
; Дизасембльовано й прокоментовано автоматично, ключові місця перевірено вручну.
; Формат рядка: СЕГМЕНТ:ЗМІЩЕННЯ  байти  команда  ; коментар
; Образ ПЗП: фіз. FC000-FFFFF (дзеркало F4000-F7FFF).
;   Перші 8 КБ показано як сегмент F400 (емулятор периферії через NMI, INT 0Fh, шрифт 80-FFh).
;   Другі 8 КБ показано як F000:E000-FFFF (основний BIOS, точки входу IBM PC/XT).
; Позначка «ймовірно» означає гіпотезу, виведену з коду, а не з документації.
; Повідомлення на екрані наведено мовою оригіналу (російською, CP866) з українським перекладом.
; ==============================================================================================
;
; ВАЖЛИВО. Роз'єм живлення материнської плати «Практика» схожий на стандартний роз'єм живлення
;   5-дюймових дисководів IBM PC, АЛЕ(!) розпіновка в нього не відповідає стандартній. Якщо підключити
;   стандартний блок живлення IBM PC, мікросхеми на материнській платі згорять.
;   Перевірте розпіновку перед подачею живлення.
;
; ==============================================================================================
;
; ## Версія 2.14-15_dk: заводський BIOS 1990 року
;
; На початку основного ПЗП (F000:E000) записано `00001 "МАГНИТ" 1990` («МАГНІТ» 1990), на екран виводиться заставка `ПЭВМ "Практик"` (ПЕОМ «Практик»). Це найраніша версія з наявних, заводський BIOS Канівського електромеханічного заводу «Магніт» (м. Канів, Черкаська область). Загальна архітектура та сама, що у версії 2.16-17: перехоплення портів через NMI, програмна емуляція периферії, мікросхеми у вікні F000:0000–0FFF. Улаштування емулятора й набір пристроїв відрізняються. Рядки, що збігаються з версією 2.16-17, прокоментовано так само; відмінності описано нижче й у заголовках процедур.
;
; ## Обробник NMI
;
; - Вектор NMI = F400:000A (`NMI_ENTRY`). Там стоїть перехід на `NMI_HANDLER` F400:006A. У версії 2.16-17 вектор указував прямо на обробник.
; - Обробник зберігає 9 регістрів і один раз ставить DS = 0040h для всіх обробників портів. У версії 2.16-17 зберігається 4 регістри.
; - Порт шукається не за таблицею на 1024 байти, а командою `repne scasw` у списку з 25 портів `nmi_port_list` (F400:00C7). Адреса обробника береться з `nmi_port_handlers` (F400:00F9). Першим у списку стоїть 3DAh, EOI (020h) — останнім; ймовірно, список упорядковано за частотою звернень.
; - Якщо порту немає в списку, OUT ігнорується, а IN повертає FFh (F400:00AE).
; - За адресою F400:0000–0009 лежать 5 слів (05A7h, 000Ah, 0, 0069h, 0), які код BIOS не читає. Ймовірно, це заголовок модуля емулятора: довжина коду й два далекі вказівники (вхід NMI і порожня процедура `retf` за адресою F400:0069).
;
; ## Чого немає порівняно з 2.16-17
;
; - **Емуляції послідовних портів 8250** (2F8–2FF, 3F8–3FF). Пошук COM1 вбудовано прямо в POST (F000:E440), але порт 3FAh не емулюється й читається як FFh, тому COM1 ніколи не знаходиться, а INT 14h одразу виходить. Саме про це в readme: «отсутствует поддержка RS232» («немає підтримки RS232»).
; - **Підпрограм `detect_com_ports` і `beep` у сегменті F400.** Звуковий сигнал — власна підпрограма в основному ПЗП (F000:F73A). Через неї таблиці розкладок клавіатури зсунуто на 1Eh (F791/F7CB/F805 замість F773/F7AD/F7E7).
; - Код емулятора закінчується на F400:05A8, далі до шрифту (F400:1C00) усе заповнено FFh.
;
; ## Інші відмінності
;
; - **INT 10h AH=0** програмує регістри 6845 через порти 3D4/3D5, як IBM, тобто через емулятор. Емулятор відкидає R0–R8, а розгортку задає обробник порту 3D8 за таблицями F400:0313. У версії 2.16-17 BIOS пише прямо в F000:0000/0002. Через це всі функції INT 10h у dk зсунуто на 4 байти.
; - Таблиця параметрів відео F0A4 і параметри дисковода EFC7 (перший байт CFh, як в IBM XT) відрізняються від версії 2.16-17.
; - **Джойстик (порт 201h)** простіший. IN повертає порт A 8255 як є, OUT дає імпульс біта 4 порту B, ймовірно запуск апаратних одновібраторів. У 2.16-17 осі імітуються програмно.
; - **Особливий вихід з INT 0Fh** під час переривання дисковода в ході програмної передачі знімає зі стека 12 байтів, а не 22: обробник порту 3F5 у dk нічого не зберігає в стеку.
; - Адреси повернення для викликів без стека лежать в E04C/E04E, а не в E06E/E070. Завантажувач зі стрічки (INT 18h) — за адресою F000:E48A.
; - У POST частина записів у регістри йде словом, а не байтом: `mov word [601h]`, `mov word cs:[0A06h]`. Зачіпаються сусідні регістри 0602h і 0A07h; у 2.16-17 це виправлено.
; - Останній байт ПЗП (F000:FFFF = 47h) доповнює суму байтів E000–FFFF до нуля.
;
; ## Джерела
;
; - Файли BIOS узято з публікації «Журнал восстановления Практика» («Журнал відновлення Практика») на сайті zxdesu, 2016: https://zxdesu.byethost32.com/2016/07/28/%d0%b6%d1%83%d1%80%d0%bd%d0%b0%d0%bb-%d0%b2%d0%be%d1%81%d1%81%d1%82%d0%b0%d0%bd%d0%be%d0%b2%d0%bb%d0%b5%d0%bd%d0%b8%d1%8f-%d0%bf%d1%80%d0%b0%d0%ba%d1%82%d0%b8%d0%ba%d0%b0/
; - Опис комп'ютера «Практик» (ПК8641) на сайті retro-computer.ru: https://retro-computer.ru/item/PRAKTIK-PK8641.html


; ##############################################################################################
; СЕГМЕНТ F400 — перші 8 КБ ПЗП (фіз. F4000-F5FFF, те саме, що FC000-FDFFF / F000:C000-DFFF)
; ##############################################################################################

; ----------------------------------------------------------------------------------------------
; rom_header — 5 слів на початку сегмента емулятора (у my на цьому місці таблиця port_index_table, 1 КБ).
; Ймовірно, заголовок завантажуваного модуля: довжина 05A7h (= байти 0002–05A8, увесь код після слова довжини),
; потім два далекі покажчики «зміщення:сегмент» з нульовим сегментом (заповнює завантажувач?):
; 000Ah:0 — вхід NMI (NMI_ENTRY), 0069h:0 — порожня far-процедура (retf). Код BIOS ці слова не читає.
; ----------------------------------------------------------------------------------------------
rom_header:
F400:0000  A705            dw     05A7h                       ; Ймовірно, довжина модуля: 05A7h байтів після цього слова (0002–05A8 — кінець коду, далі FFh)
F400:0002  0A00            dw     000Ah                       ; Зміщення входу NMI = 000Ah (NMI_ENTRY) — те саме значення POST пише у вектор INT 2 (E197)
F400:0004  0000            dw     0000h                       ; Сегмент до зміщення 000Ah = 0 (ймовірно, підставляється під час завантаження або не використовується)
F400:0006  6900            dw     0069h                       ; Зміщення far-заглушки retf F400:0069 (ймовірно, точка ініціалізації модуля — порожня)
F400:0008  0000            dw     0000h                       ; Сегмент = 0 (як у F400:0004)

; ----------------------------------------------------------------------------------------------
; NMI_ENTRY — точка входу NMI: вектор INT 02h = F400:000A (встановлюється в POST, E197).
; Короткий перехід на NMI_HANDLER F400:006A (у my вектор вказує прямо на обробник F400:046C).
; ----------------------------------------------------------------------------------------------
NMI_ENTRY:
F400:000A  EB5E            jmp    NMI_HANDLER                 ; Вхід NMI: перехід на NMI_HANDLER (F400:006A)
F400:000C  90              db     90h                         ; NOP-заповнювач після короткого jmp; INT0F_IRQ_DISPATCH починається з F400:000D

; ----------------------------------------------------------------------------------------------
; INT0F_IRQ_DISPATCH — спільний обробник апаратних переривань (вектор INT 0Fh = F400:000D), замінює 8259.
; Читає регістр запитів F000:0200 (старший байт): біт 15 — дисковод (INT 0Eh), біт 14 — таймер (INT 08h),
; біт 13 — клавіатура (INT 09h), біт 12 — COM1 (INT 0Ch; у dk вектор INT 0Ch — заглушка IRET, RS-232 немає).
; За один вхід обслуговується одне джерело за пріоритетом. Особливий випадок: IRQ дисковода під час програмної
; передачі даних FDC (0040:00B9 біт 3 = 0) — стек зрізається до адреси повернення в NMI_HANDLER (F400:00AC).
; ----------------------------------------------------------------------------------------------
INT0F_IRQ_DISPATCH:
F400:000D  06              push   es                          ; Зберігаємо ES перерваної програми
F400:000E  1E              push   ds                          ; Зберігаємо DS
F400:000F  50              push   ax                          ; Зберігаємо AX
F400:0010  FC              cld                                ; Скидання прапорця напрямку для рядкових операцій
F400:0011  B84000          mov    ax, 40h                     ; Сегмент області даних BIOS 0040h…
F400:0014  8ED8            mov    ds, ax                      ; …у DS
F400:0016  B800F0          mov    ax, 0F000h                  ; Сегмент регістрів апаратури F000h…
F400:0019  8EC0            mov    es, ax                      ; …в ES
F400:001B  26A10002        mov    ax, word es:[200h]          ; AX = регістр стану запитів переривань F000:0200 (AH = біти 15–8)
F400:001F  D0E4            shl    ah, 1                       ; Біт 15 → CF: запит від контролера дисковода?
F400:0021  7316            jae    loc_0039                    ; Немає запиту FDC — перевіряємо наступне джерело
F400:0023  A0B900          mov    al, byte [0B9h]             ; AL = 0040:00B9 — тіньова копія регістра керування дисководом F000:0601 (DOR)
F400:0026  A808            test   al, 8                       ; Біт 3 = 1 — програмна передача даних FDC зараз не йде?
F400:0028  750F            jne    loc_0039                    ; Так — IRQ FDC тут не обслуговуємо (на нього чекає опитування в nmi_port_3F2/3F5), до таймера
F400:002A  83C40C          add    sp, 0Ch                     ; Знімаємо 6 слів (push es/ds/ax + IP/CS/FLAGS переривання): на вершині — повернення в NMI_HANDLER (00AC)
F400:002D  0C08            or     al, 8                       ; Відновлюємо біт 3 (вихід із режиму програмної передачі даних)
F400:002F  A2B900          mov    byte [0B9h], al             ; Оновлюємо тіньову копію DOR у 0040:00B9
F400:0032  26A20106        mov    byte es:[601h], al          ; …і записуємо в апаратний регістр керування дисководом F000:0601
F400:0036  CD0E            int    0Eh                         ; Викликаємо обробник переривання дисковода INT 0Eh (ймовірно, ставить прапорець 0040:003E біт 7)
F400:0038  C3              ret                                ; Повернення просто в NMI_HANDLER (після call bx) — операцію FDC завершено

loc_0039:    ; посилання: 0021 0028
F400:0039  D0E4            shl    ah, 1                       ; Біт 14 → CF: запит від системного таймера (канал 0 8253)?
F400:003B  730A            jae    loc_0047                    ; Ні — перевіряємо клавіатуру
F400:003D  26A00900        mov    al, byte es:[9]             ; Читання F000:0009 — ймовірно, квитування/скидання запиту переривання таймера
F400:0041  58              pop    ax                          ; Відновлюємо AX
F400:0042  1F              pop    ds                          ; Відновлюємо DS
F400:0043  07              pop    es                          ; Відновлюємо ES
F400:0044  CD08            int    8                           ; Викликаємо обробник таймера INT 08h (тік годинника, 18.2 Гц)
F400:0046  CF              iret                               ; Повернення в перервану програму

loc_0047:    ; посилання: 003B
F400:0047  D0E4            shl    ah, 1                       ; Біт 13 → CF: запит від клавіатури?
F400:0049  7314            jae    loc_005F                    ; Ні — перевіряємо COM1
F400:004B  26A00300        mov    al, byte es:[3]             ; AL = F000:0003 — порт B реального 8255 (аналог порту 61h)
F400:004F  0C20            or     al, 20h                     ; Ставимо біт 5 — ймовірно, блокування/квитування запиту IRQ клавіатури
F400:0051  26A20300        mov    byte es:[3], al             ; Записуємо в порт B 8255
F400:0055  CD09            int    9                           ; Викликаємо обробник клавіатури INT 09h (він прочитає скан-код з порту 60h)
F400:0057  24DF            and    al, 0DFh                    ; Знімаємо біт 5 (AL збережено INT 09h; EOI в порт 20h теж знімає цей біт)
F400:0059  26A20300        mov    byte es:[3], al             ; Записуємо порт B 8255 назад — дозволяємо наступний запит клавіатури
F400:005D  EB06            jmp    loc_0065                    ; До виходу

loc_005F:    ; посилання: 0049
F400:005F  D0E4            shl    ah, 1                       ; Біт 12 → CF: запит від COM1 (8250)?
F400:0061  7302            jae    loc_0065                    ; Запитів немає — вихід
F400:0063  CD0C            int    0Ch                         ; Викликаємо INT 0Ch (IRQ COM1); у dk вектор — заглушка IRET F000:FF53

loc_0065:    ; посилання: 005D 0061
F400:0065  58              pop    ax                          ; Відновлюємо AX
F400:0066  1F              pop    ds                          ; Відновлюємо DS
F400:0067  07              pop    es                          ; Відновлюємо ES
F400:0068  CF              iret                               ; Повернення з переривання

; ----------------------------------------------------------------------------------------------
; Порожня far-процедура (retf). З коду недосяжна (перед нею iret), посилання лише з rom_header (слово F400:0006).
; ----------------------------------------------------------------------------------------------
F400:0069  CB              db     0CBh                        ; retf — ймовірно, порожня far-точка входу модуля (ініціалізація), на неї вказує F400:0006

; ----------------------------------------------------------------------------------------------
; NMI_HANDLER — обробник NMI (через NMI_ENTRY F400:000A): програмна емуляція портів введення-виведення IBM PC.
; F000:0200 — клямка (защіпка): біти 0–9 = номер порту, біт 10 = 1 під час запису (OUT), біт 11 = NMI викликано зверненням до порту.
; F000:0400/0401 — дані OUT (парний/непарний байт шини). Номер порту шукається repne scasw у списку nmi_port_list
; (25 слів, F400:00C7), адреса обробника береться з nmi_port_handlers (F400:00F9); не знайдено — «немає пристрою».
; Обробник викликається з ZF=1 при IN, ZF=0 при OUT; DS=0040, ES=F000, DX = клямка, AX = номер порту, SI = адреса
; обробника; збережено 9 регістрів: [bp]=AX (сюди результат IN), +2 BX, +4 CX, +6 DX, +8 SI, +0Ah DI, +0Ch BP, +0Eh DS, +10h ES.
; ----------------------------------------------------------------------------------------------
NMI_HANDLER:    ; посилання: 000A
F400:006A  06              push   es                          ; Зберігаємо ES (кадр: [bp+10h])
F400:006B  1E              push   ds                          ; Зберігаємо DS ([bp+0Eh]) — у dk DS=0040 встановлюється тут один раз для всіх обробників
F400:006C  55              push   bp                          ; Зберігаємо BP ([bp+0Ch])
F400:006D  57              push   di                          ; Зберігаємо DI ([bp+0Ah]) — потрібен для пошуку в nmi_port_list
F400:006E  56              push   si                          ; Зберігаємо SI ([bp+8]) — у ньому буде адреса обробника порту
F400:006F  52              push   dx                          ; Зберігаємо DX ([bp+6]) — у ньому буде копія клямки
F400:0070  51              push   cx                          ; Зберігаємо CX ([bp+4]) — лічильник для repne scasw
F400:0071  53              push   bx                          ; Зберігаємо BX ([bp+2])
F400:0072  50              push   ax                          ; Зберігаємо AX перерваної програми ([bp+0] — сюди обробник пише результат IN)
F400:0073  8BEC            mov    bp, sp                      ; BP → кадр збережених регістрів
F400:0075  B84000          mov    ax, 40h                     ; Сегмент області даних BIOS 0040h (тіньові регістри емулятора 0040:009E–00BD)…
F400:0078  8ED8            mov    ds, ax                      ; …у DS — спільний для всіх обробників (у my кожен обробник встановлював DS сам)
F400:007A  B800F0          mov    ax, 0F000h                  ; Сегмент регістрів апаратури F000h…
F400:007D  8EC0            mov    es, ax                      ; …в ES (ES лишається F000 в усіх обробниках портів)
F400:007F  26A10002        mov    ax, word es:[200h]          ; AX = клямка F000:0200: біти 0–9 — порт, біт 10 — OUT, біт 11 — NMI від звернення до порту
F400:0083  F6C408          test   ah, 8                       ; Біт 11: NMI викликано зверненням до порту введення-виведення?
F400:0086  7430            je     loc_00B8                    ; Ні (інше джерело NMI) — лише квитуємо й виходимо
F400:0088  8BD0            mov    dx, ax                      ; DX = повна копія клямки (DH біт 2 = OUT, біт 3 = порт) — доступна обробникам
F400:008A  25FF03          and    ax, 3FFh                    ; AX = номер порту 000–3FFh
F400:008D  BFC700          mov    di, 0C7h                    ; DI → nmi_port_list (F400:00C7) — список емульованих портів
F400:0090  B91900          mov    cx, 19h                     ; CX = 25 (19h) портів у списку
F400:0093  FC              cld                                ; Пошук уперед за списком
F400:0094  06              push   es                          ; Зберігаємо ES = F000
F400:0095  8CCB            mov    bx, cs                      ; ES = CS = F400 — список лежить у ПЗП…
F400:0097  8EC3            mov    es, bx                      ; …ES = F400 для scasw
F400:0099  F2AF            repne scasw ax, word es:[di]       ; Лінійний пошук номера порту в списку (у my — прямий індекс за 1024-байтною таблицею)
F400:009B  07              pop    es                          ; Відновлюємо ES
F400:009C  7510            jne    loc_00AE                    ; Порт не знайдено в списку — гілка «немає пристрою»
F400:009E  81EFC900        sub    di, 0C9h                    ; DI = 2*індекс знайденого порту (scasw залишив DI за збіглим словом: DI−00C9h)
F400:00A2  2E8BB5F900      mov    si, word cs:[di + 0F9h]     ; SI = адреса обробника з nmi_port_handlers (F400:00F9 + 2*індекс)
F400:00A7  F6C604          test   dh, 4                       ; Біт 10 клямки (OUT): ZF=1 — читання IN, ZF=0 — запис OUT; прапорець передається обробнику
