F000:F73E  B83305          mov    ax, 533h                    ; AX = 0533h (1331) — дільник ≈ 896 Гц для 1,19 МГц; емулятор перерахує під ~1 МГц
F000:F741  E642            out    42h, al                     ; OUT 42h: молодший байт (емулятор накопичує байти в 0040:00B0)
F000:F743  8AC4            mov    al, ah                      ; AL = старший байт дільника
F000:F745  E642            out    42h, al                     ; OUT 42h: старший байт → перерахунок і завантаження каналу 2 (F000:0A04)
F000:F747  E461            in     al, 61h                     ; IN 61h → nmi_port_061: порт B 8255 (біт 6 зведено до логіки IBM)
F000:F749  8AE0            mov    ah, al                      ; AH = вихідне значення порту 61h
F000:F74B  0C03            or     al, 3                       ; Біт 0 — GATE2 (дозвіл лічби), біт 1 — дані динаміка
F000:F74D  E661            out    61h, al                     ; OUT 61h: вмикаємо звук
F000:F74F  2BC9            sub    cx, cx                      ; CX = 0 — 65536 ітерацій внутрішнього циклу

