F000:F767  8AE8            mov    ch, al                      ; CH = біти 16–19 фізичної адреси (сторінка)
F000:F769  24F0            and    al, 0F0h                    ; AL = молодша частина сегмента ×16
F000:F76B  03C3            add    ax, bx                      ; AX = молодші 16 біт фізичної адреси (сегмент×16 + BX)
F000:F76D  7302            jae    loc_F771                    ; без перенесення → сторінка не змінюється
F000:F76F  FEC5            inc    ch                          ; перенесення → сторінка +1

loc_F771:    ; посилання: F76D
F000:F771  50              push   ax                          ; зберігаємо початкову адресу для перевірки межі 64 КБ
F000:F772  E604            out    4, al                       ; порт 04h — адреса каналу 2 ПДП, молодший байт
