F000:F784  50              push   ax                          ; зберігаємо секторів×128
F000:F785  BB0600          mov    bx, 6                       ; BX=6 → байт 3 таблиці параметрів дисковода (код розміру сектора N)
F000:F788  E8E3F6          call   sub_EE6E                    ; AH = байт параметрів дисковода за вектором INT 1Eh (0000:0078)
