; ----------------------------------------------------------------------------------------------
; dat_F791 — таблиця трансляції скан-кодів 01h..3Ah для латиниці з Shift (верхній регістр).
; Індекс = скан-код-1 (xlat в INT 09h, F000:EB8F). FFh = клавіша без ASCII-коду
; (модифікатори), 00h = розширений код. Вибирається в F000:EB33 за вимкненого РУС (0040:0018 біт 2 = 0).
; ----------------------------------------------------------------------------------------------
dat_F791:    ; посилання: EB33
F000:F791  1B              db     1Bh                         ; скан 01h Esc → 1Bh
F000:F792  21402324255E…   db     '!@#$%^&*()_+'              ; скан 02h–0Dh із Shift: верхній ряд !@#$%^&*()_+
F000:F79E  0800            db     08h,00h                     ; скан 0Eh BackSpace → 08h; скан 0Fh Shift+Tab → 00h (розширений код 0F00h)
F000:F7A0  515745525459…   db     'QWERTYUIOP{}'              ; скан 10h–1Bh із Shift: QWERTYUIOP{}
F000:F7AC  0DFF            db     0Dh,0FFh                    ; скан 1Ch Enter → 0Dh; скан 1Dh Ctrl → FFh (модифікатор, без символу)
F000:F7AE  415344464748…   db     'ASDFGHJKL:"~'              ; скан 1Eh–29h із Shift: ASDFGHJKL:"~
F000:F7BA  FF              db     0FFh                        ; скан 2Ah лівий Shift → FFh (модифікатор)
F000:F7BB  7C5A58435642…   db     '|ZXCVBNM<>?'               ; скан 2Bh–35h із Shift: |ZXCVBNM<>?
F000:F7C6  FF00FF20FF      db     0FFh,00h,0FFh,20h,0FFh      ; скан 36h пр.Shift FFh, 37h PrtSc 00h, 38h Alt FFh, 39h пробіл 20h, 3Ah CapsLock FFh

; ----------------------------------------------------------------------------------------------
; dat_F7CB — таблиця скан-кодів 01h..3Ah для російських літер без Shift (нижній регістр, CP866).
; Вибирається в F000:EB8A за увімкненого режиму РУС (ймовірно, 0040:0018 біт 2 — перемикається в F000:E94D).
; Розкладка ЙЦУКЕН; літера ё на місці клавіші «/» (скан 35h).
; ----------------------------------------------------------------------------------------------
dat_F7CB:    ; посилання: EB8A
F000:F7CB  1B              db     1Bh                         ; скан 01h Esc → 1Bh
F000:F7CC  313233343536…   db     '1234567890-='              ; скан 02h–0Dh без Shift: цифри 1234567890-=
F000:F7D8  0809            db     08h,09h                     ; скан 0Eh BackSpace → 08h; скан 0Fh Tab → 09h
F000:F7DA  A9E6E3AAA5AD…   db     'йцукенгшщзхъ'              ; скан 10h–1Bh: йцукенгшщзхъ (CP866 A9h,E6h,...)
F000:F7E6  0DFF            db     0Dh,0FFh                    ; скан 1Ch Enter → 0Dh; скан 1Dh Ctrl → FFh
F000:F7E8  E4EBA2A0AFE0…   db     'фывапролджэ`'              ; скан 1Eh–29h: фывапролджэ і ` (клавіша ~ залишена латинською)
F000:F7F4  FF              db     0FFh                        ; скан 2Ah лівий Shift → FFh
F000:F7F5  5CEFE7E1ACA8…   db     '\ячсмитьбюё'               ; скан 2Bh–35h: \ячсмитьбюё (ё замість «/»)
F000:F800  FF2AFF20FF      db     0FFh,2Ah,0FFh,20h,0FFh      ; скан 36h пр.Shift FFh, 37h сірий * → 2Ah, 38h Alt FFh, 39h пробіл 20h, 3Ah CapsLock FFh

; ----------------------------------------------------------------------------------------------
; dat_F805 — таблиця скан-кодів 01h..3Ah для російських літер із Shift (верхній регістр, CP866).
; Вибирається в F000:EB3D за Shift і увімкненого РУС (0040:0018 біт 2).
