F000:F812  0800            db     08h,00h                     ; скан 0Eh BackSpace → 08h; скан 0Fh Shift+Tab → 00h (розширений код)
F000:F814  8996938A858D…   db     'ЙЦУКЕНГШЩЗХЪ'              ; скан 10h–1Bh із Shift: ЙЦУКЕНГШЩЗХЪ (CP866 89h,96h,...)
