F000:F82F  7C9F97918C88…   db     '|ЯЧСМИТЬБЮЁ'               ; скан 2Bh–35h із Shift: |ЯЧСМИТЬБЮЁ
F000:F83A  FF00FF20FF0000  db     0FFh,00h,0FFh,20h,0FFh,00h,00h ; скан 36h прав.Shift FFh, 37h PrtSc 00h, 38h Alt FFh, 39h пробіл 20h, 3Ah CapsLock FFh; 00h,00h — заповнювач до F841

