; ----------------------------------------------------------------------------------------------
; INT15_CASSETTE — INT 15h (точка IBM F000:F859): магнітофонний інтерфейс, алгоритм як в IBM PC.
; AH=0/1 мотор увімк./вимк. (тут заглушки), 2 — читання блоків у ES:BX (CX байт),
; 3 — запис блоків з ES:BX. Вихід: CF=1 помилка, AH = код (1 CRC, 2 втрата даних, 4 немає даних, 80h неправильна функція).
; Вимірювання/генерація інтервалів — каналом 2 справжнього 8253, відображеного в F000:0A00..0A06 (канал 2 = F000:0A04).
; Вихід retf 2 відкидає збережені FLAGS, щоб повернути CF результату.
; ----------------------------------------------------------------------------------------------
INT15_CASSETTE:
F000:F859  FA              cli                                ; забороняємо переривання на час налаштування таймера
F000:F85A  1E              push   ds                          ; зберігаємо DS
F000:F85B  50              push   ax                          ; зберігаємо AX (AH = номер функції)
F000:F85C  E461            in     al, 61h                     ; читаємо порт 61h (порт B 8255, емульований через NMI → F000:0003)
F000:F85E  24FD            and    al, 0FDh                    ; біт 1 = 0: вимкнути виведення на динамік
F000:F860  0C01            or     al, 1                       ; біт 0 = 1: відкрити вхід GATE2 каналу 2 таймера
F000:F862  E661            out    61h, al                     ; записуємо порт 61h
F000:F864  B0B6            mov    al, 0B6h                    ; керівне слово 8253: канал 2, мол.+ст. байт, режим 3 (меандр), двійковий рахунок
F000:F866  E643            out    43h, al                     ; у порт 43h (емуляція → регістр керування 8253 F000:0A06)
F000:F868  33C0            xor    ax, ax                      ; AX = 0 — початковий рахунок 0 = 65536
F000:F86A  2EA2040A        mov    byte cs:[0A04h], al         ; мол. байт рахунку каналу 2 прямо в 8253 F000:0A04 (без NMI-емуляції)
