F000:FEFF  57EF            dw     INT0E_DISKETTE_IRQ          ; INT 0Eh — переривання дисковода, F000:EF57
F000:FF01  0D00            dw     000Dh                       ; INT 0Fh — спільний обробник апаратних переривань F400:000D (сегмент F400 встановлюється в E1A9)

